class Point:
    def __init__(self, x, y): self.x, self.y = x, y
    def __getnewargs__(self): return (self.x + 1, self.y + 1)
import pickle
p = Point(1, 2)
print(pickle.loads(pickle.dumps(p)).x)

from functools import singledispatch
@singledispatch
def f(arg): return 'default'
@f.register
@f.register(int)
def _(arg): return 'int'
print(f(5), f('5'))

