def neumaier_sum(a, b):
    s = a + b
    c = s - a
    return s + (b - c)
print(neumaier_sum(1.0, 1e-16) == 1.0 + 1e-16)

class Awaitable:
    def __await__(self):
        yield 42
        return 'done'
async def coro():
    return await Awaitable()
import asyncio
print(asyncio.run(coro()))

